import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ExclamationTriangleIcon, ArrowPathIcon } from '@heroicons/react/24/outline';
import apiService from '../../services/api';
import { useNotification } from '../../hooks/useNotification';

const DNSVerificationStep = ({ domainId, data, onChange, errors, onNext, onPrev, canGoBack, saving }) => {
  const [verifying, setVerifying] = useState(false);
  const [dnsRecords, setDnsRecords] = useState([]);
  const [verificationStatus, setVerificationStatus] = useState(data.verificationStatus || 'pending');
  const { showNotification } = useNotification();

  useEffect(() => {
    if (data.dnsRecords) {
      setDnsRecords(data.dnsRecords);
    }
    loadDNSRecords();
  }, [domainId]);

  const loadDNSRecords = async () => {
    try {
      const response = await dnsAPI.getRecords(domainId);
      setDnsRecords(response.data.results || []);

      // Actualizar datos del paso
      onChange('dnsRecords', response.data.results || []);
    } catch (error) {
      console.error('Error loading DNS records:', error);
      showNotification('Error al cargar registros DNS', 'error');
    }
  };

  const verifyDNS = async () => {
    try {
      setVerifying(true);
      const response = await dnsAPI.verifyDomain(domainId);

      // Esperar un momento para que se complete la verificación
      setTimeout(async () => {
        await loadDNSRecords();
        setVerificationStatus('completed');
        onChange('verificationStatus', 'completed');
        onChange('dnsVerified', true);
        showNotification('Verificación DNS completada', 'success');
      }, 3000);

    } catch (error) {
      console.error('Error verifying DNS:', error);
      showNotification('Error en la verificación DNS', 'error');
      setVerificationStatus('error');
      onChange('verificationStatus', 'error');
    } finally {
      setVerifying(false);
    }
  };

  const getRecordStatus = (record) => {
    if (record.validation_status === 'valid') {
      return { icon: CheckCircleIcon, color: 'text-green-500', bg: 'bg-green-50' };
    } else if (record.validation_status === 'invalid') {
      return { icon: ExclamationTriangleIcon, color: 'text-red-500', bg: 'bg-red-50' };
    } else {
      return { icon: ArrowPathIcon, color: 'text-yellow-500', bg: 'bg-yellow-50' };
    }
  };

  const getOverallStatus = () => {
    if (dnsRecords.length === 0) return 'pending';

    const validRecords = dnsRecords.filter(r => r.validation_status === 'valid');
    const invalidRecords = dnsRecords.filter(r => r.validation_status === 'invalid');

    if (invalidRecords.length > 0) return 'warning';
    if (validRecords.length === dnsRecords.length) return 'success';
    return 'pending';
  };

  const overallStatus = getOverallStatus();

  return (
    <div className="space-y-6">
      {/* Introducción */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <svg className="h-5 w-5 text-blue-400" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
            </svg>
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">
              Verificación de Registros DNS
            </h3>
            <div className="mt-2 text-sm text-blue-700">
              <p>
                Verificaremos los registros DNS existentes de tu dominio para identificar
                la configuración actual de SPF, DKIM y DMARC.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Estado general */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-medium text-gray-900">Estado de Verificación</h3>
          <button
            onClick={verifyDNS}
            disabled={verifying}
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {verifying ? (
              <>
                <ArrowPathIcon className="animate-spin -ml-1 mr-2 h-4 w-4" />
                Verificando...
              </>
            ) : (
              <>
                <ArrowPathIcon className="-ml-1 mr-2 h-4 w-4" />
                Verificar DNS
              </>
            )}
          </button>
        </div>

        <div className={`
          p-4 rounded-lg border-2 border-dashed
          ${
            overallStatus === 'success'
              ? 'border-green-300 bg-green-50'
              : overallStatus === 'warning'
              ? 'border-yellow-300 bg-yellow-50'
              : 'border-gray-300 bg-gray-50'
          }
        `}>
          <div className="text-center">
            {overallStatus === 'success' && (
              <>
                <CheckCircleIcon className="mx-auto h-12 w-12 text-green-500" />
                <h3 className="mt-2 text-sm font-medium text-green-900">
                  Verificación Completada
                </h3>
                <p className="mt-1 text-sm text-green-700">
                  Todos los registros DNS han sido verificados correctamente.
                </p>
              </>
            )}
            {overallStatus === 'warning' && (
              <>
                <ExclamationTriangleIcon className="mx-auto h-12 w-12 text-yellow-500" />
                <h3 className="mt-2 text-sm font-medium text-yellow-900">
                  Verificación con Advertencias
                </h3>
                <p className="mt-1 text-sm text-yellow-700">
                  Se encontraron algunos problemas en los registros DNS.
                </p>
              </>
            )}
            {overallStatus === 'pending' && (
              <>
                <ArrowPathIcon className="mx-auto h-12 w-12 text-gray-400" />
                <h3 className="mt-2 text-sm font-medium text-gray-900">
                  Verificación Pendiente
                </h3>
                <p className="mt-1 text-sm text-gray-700">
                  Haz clic en "Verificar DNS" para comenzar la verificación.
                </p>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Lista de registros DNS */}
      {dnsRecords.length > 0 && (
        <div className="bg-white border border-gray-200 rounded-lg">
          <div className="px-4 py-3 border-b border-gray-200">
            <h3 className="text-lg font-medium text-gray-900">Registros DNS Encontrados</h3>
          </div>
          <div className="divide-y divide-gray-200">
            {dnsRecords.map((record, index) => {
              const status = getRecordStatus(record);
              const StatusIcon = status.icon;

              return (
                <div key={index} className="p-4">
                  <div className="flex items-start">
                    <div className={`flex-shrink-0 p-1 rounded-full ${status.bg}`}>
                      <StatusIcon className={`h-5 w-5 ${status.color}`} />
                    </div>
                    <div className="ml-3 flex-1">
                      <div className="flex items-center justify-between">
                        <div>
                          <h4 className="text-sm font-medium text-gray-900">
                            {record.record_type} - {record.name || '@'}
                          </h4>
                          <p className="text-sm text-gray-600 mt-1 font-mono break-all">
                            {record.value}
                          </p>
                        </div>
                        <div className="ml-4 flex-shrink-0">
                          <span className={`
                            inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                            ${
                              record.validation_status === 'valid'
                                ? 'bg-green-100 text-green-800'
                                : record.validation_status === 'invalid'
                                ? 'bg-red-100 text-red-800'
                                : 'bg-yellow-100 text-yellow-800'
                            }
                          `}>
                            {record.validation_status === 'valid' ? 'Válido' :
                             record.validation_status === 'invalid' ? 'Inválido' : 'Pendiente'}
                          </span>
                        </div>
                      </div>
                      {record.validation_error && (
                        <div className="mt-2 text-sm text-red-600">
                          <strong>Error:</strong> {record.validation_error}
                        </div>
                      )}
                      {record.last_checked && (
                        <div className="mt-1 text-xs text-gray-500">
                          Última verificación: {new Date(record.last_checked).toLocaleString()}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Recomendaciones */}
      {overallStatus === 'warning' && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <div className="flex">
            <div className="flex-shrink-0">
              <ExclamationTriangleIcon className="h-5 w-5 text-yellow-400" />
            </div>
            <div className="ml-3">
              <h3 className="text-sm font-medium text-yellow-800">
                Recomendaciones
              </h3>
              <div className="mt-2 text-sm text-yellow-700">
                <ul className="list-disc list-inside space-y-1">
                  <li>Revisa los registros marcados como inválidos</li>
                  <li>Verifica la sintaxis de los registros SPF y DMARC</li>
                  <li>Asegúrate de que los registros DKIM estén correctamente configurados</li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Error de validación */}
      {errors.dnsVerified && (
        <div className="text-sm text-red-600">
          {errors.dnsVerified}
        </div>
      )}

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onPrev}
          disabled={!canGoBack}
          className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <button
          onClick={onNext}
          disabled={saving || verifying}
          className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {saving ? 'Guardando...' : 'Siguiente'}
        </button>
      </div>
    </div>
  );
};

export default DNSVerificationStep;
